import { createHash } from 'node:crypto';
import { AppError, ConflictError, ValidationError } from '../../errors';
import type { TradeAction } from '../../services/tradeNextAction';
export const hash = (value: unknown) =>
  createHash('sha256').update(JSON.stringify(value)).digest('hex');
export function notice(action: TradeAction) {
  // URLs are generated by the authoritative trade policy and never persisted or accepted as input.
  if (
    !/^\/(offers\?tab=(received|sent)|deal-room\/[a-f0-9-]+|payments\/[a-f0-9-]+|shipments\/[a-f0-9-]+)$/.test(
      action.actionPath,
    )
  )
    throw new AppError('Current notification link is unavailable', 503, 'NOTICE_LINK_UNAVAILABLE');
  const responsibleParty = action.requiresAction
    ? 'you'
    : action.kind === 'complete'
      ? 'none'
      : 'other';
  const fingerprint = hash([
    action.id,
    action.kind,
    action.description,
    responsibleParty,
    action.requiresAction,
  ]);
  return {
    fingerprint,
    kind: action.kind,
    title: action.title,
    description: action.description,
    requiresAction: action.requiresAction,
    responsibleParty,
    actionLabel: action.actionLabel,
    actionPath: action.actionPath,
  };
}
export function pageInput(query: Record<string, unknown>) {
  const filter = query.filter ?? 'all';
  if (filter !== 'all' && filter !== 'unread')
    throw new ValidationError('Invalid notification filter');
  const limit = query.limit === undefined ? 25 : Number(query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100)
    throw new ValidationError('Limit must be between 1 and 100');
  if (
    query.cursor !== undefined &&
    (typeof query.cursor !== 'string' || query.cursor.length > 1024)
  )
    throw new ValidationError('Invalid notification cursor');
  return { filter, limit, cursor: query.cursor as string | undefined };
}
export function cursorOffset(cursor: string | undefined, scope: string, revision: string): number {
  if (!cursor) return 0;
  let decoded: unknown;
  try {
    decoded = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8')) as unknown;
  } catch {
    throw new ValidationError('Invalid notification cursor');
  }
  if (!decoded || typeof decoded !== 'object' || Array.isArray(decoded))
    throw new ValidationError('Invalid notification cursor');
  const value = decoded as Record<string, unknown>;
  if (value.scope !== scope || value.revision !== revision)
    throw new ConflictError('Notifications changed; refresh the current feed');
  if (
    typeof value.offset !== 'number' ||
    !Number.isInteger(value.offset) ||
    value.offset < 1 ||
    value.offset > 1000
  )
    throw new ValidationError('Invalid notification cursor');
  return value.offset;
}
